CREATE TABLE IF NOT EXISTS shops (id INTEGER PRIMARY KEY, name TEXT, address TEXT, phone TEXT, currency TEXT, language TEXT, used_oil_drum_capacity REAL, manual_price_allowed INTEGER, wholesale_mode TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, shop_id INTEGER, email TEXT UNIQUE, password_hash TEXT, full_name TEXT, role TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS role_permissions (role TEXT, permission_key TEXT, PRIMARY KEY(role, permission_key));
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY, shop_id INTEGER, name TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS brands (id INTEGER PRIMARY KEY, shop_id INTEGER, name TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, shop_id INTEGER, sku TEXT, barcode TEXT, name TEXT, brand_id INTEGER, category_id INTEGER, packing TEXT, unit TEXT, variant TEXT, mfd_date TEXT, exp_date TEXT, offer TEXT, cost_price REAL, stock_qty REAL, low_stock_threshold REAL, price_returning REAL, price_walking REAL, price_wholesale REAL, wholesale_min_qty REAL, active INTEGER, created_at TEXT);
CREATE TABLE IF NOT EXISTS services (id INTEGER PRIMARY KEY, shop_id INTEGER, name TEXT, price REAL, active INTEGER, created_at TEXT);
CREATE TABLE IF NOT EXISTS containers (id INTEGER PRIMARY KEY, shop_id INTEGER, product_id INTEGER, barcode TEXT, original_volume REAL, remaining_volume REAL, status TEXT, opened_at TEXT, source_order_id INTEGER);
CREATE TABLE IF NOT EXISTS container_splits (id INTEGER PRIMARY KEY, container_id INTEGER, sold_qty REAL, sold_at TEXT, order_id INTEGER);
CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY, shop_id INTEGER, name TEXT, phone TEXT, customer_type TEXT, credit_balance REAL, last_visit_at TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS vehicles (id INTEGER PRIMARY KEY, customer_id INTEGER, registration TEXT, make TEXT, model TEXT, mileage INTEGER, created_at TEXT);
CREATE TABLE IF NOT EXISTS vendors (id INTEGER PRIMARY KEY, shop_id INTEGER, name TEXT, contact TEXT, phone TEXT, payable_balance REAL, created_at TEXT);
CREATE TABLE IF NOT EXISTS vendor_payables (id INTEGER PRIMARY KEY, vendor_id INTEGER, amount REAL, due_date TEXT, status TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS accounts (id INTEGER PRIMARY KEY, shop_id INTEGER, name TEXT, type TEXT, balance REAL, active INTEGER, created_at TEXT);
CREATE TABLE IF NOT EXISTS account_transactions (id INTEGER PRIMARY KEY, account_id INTEGER, amount REAL, type TEXT, reference TEXT, related_account_id INTEGER, created_at TEXT);
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY, shop_id INTEGER, customer_id INTEGER, user_id INTEGER, total REAL, payment_account_id INTEGER, payment_method TEXT, status TEXT, vehicle_id INTEGER, mileage INTEGER, notes TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY, order_id INTEGER, kind TEXT, ref_id INTEGER, product_name TEXT, qty REAL, unit_price REAL, line_total REAL, container_id INTEGER);
CREATE TABLE IF NOT EXISTS used_oil_drum (id INTEGER PRIMARY KEY, shop_id INTEGER, current_litres REAL, capacity REAL);
CREATE TABLE IF NOT EXISTS used_oil_log (id INTEGER PRIMARY KEY, drum_id INTEGER, litres REAL, type TEXT, source_order_id INTEGER, created_at TEXT);
CREATE TABLE IF NOT EXISTS expenses (id INTEGER PRIMARY KEY, shop_id INTEGER, category TEXT, amount REAL, account_id INTEGER, date TEXT, note TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT);
